/* CSEC Study Hub — practice bank
 *
 * These questions are written for this hub in CSEC Paper 01 style. They are not
 * copies of CXC past papers — CXC owns those and sells them, so the hub links
 * out to the official store rather than reproducing them. Every item is tagged
 * to a syllabus strand so a wrong answer moves the right strand in the mastery
 * model and comes back in the daily plan.
 *
 * Fields: id, subj, strand, form (earliest form it fits), diff 1-3,
 *         q, opts[], a (index of correct option), why, tech (exam technique)
 */
window.CSEC_QUESTIONS = [

/* ============================ MATHEMATICS ============================ */
{id:'ma1',subj:'mathematics',strand:'ma-number',form:1,diff:1,q:'Simplify: 3/4 + 2/5',opts:['23/20','5/9','23/40','6/20'],a:0,why:'Use a common denominator of 20: 3/4 = 15/20 and 2/5 = 8/20. 15/20 + 8/20 = 23/20, which is 1 3/20.',tech:'Never add denominators. Find the LCM first, convert both, then add only the numerators.'},
{id:'ma2',subj:'mathematics',strand:'ma-number',form:2,diff:2,q:'Write 0.00045 in standard form.',opts:['4.5 × 10⁻⁴','45 × 10⁻⁵','4.5 × 10⁴','0.45 × 10⁻³'],a:0,why:'Standard form needs one non-zero digit before the point. Moving the point 4 places right gives 4.5, so the index is −4.',tech:'Small number → negative index. Large number → positive index. Count the jumps of the decimal point.'},
{id:'ma3',subj:'mathematics',strand:'ma-number',form:2,diff:1,q:'Evaluate (2³)²',opts:['64','32','12','36'],a:0,why:'Power of a power means multiply the indices: (2³)² = 2⁶ = 64.',tech:'Multiply indices for a power of a power; add them when multiplying the same base.'},
{id:'ma4',subj:'mathematics',strand:'ma-consumer',form:2,diff:2,q:'A television is marked $2 400 before VAT. VAT is charged at 12.5%. What is the price including VAT?',opts:['$2 700.00','$2 412.50','$2 550.00','$3 000.00'],a:0,why:'VAT = 12.5% of 2 400 = $300. Total = 2 400 + 300 = $2 700.',tech:'Adding a percentage? Multiply by 1.125 in one step instead of finding the VAT and adding it — fewer chances to slip.'},
{id:'ma5',subj:'mathematics',strand:'ma-consumer',form:3,diff:2,q:'Kavita borrows $8 000 at 5% simple interest per annum for 3 years. How much interest does she pay?',opts:['$1 200','$400','$1 260','$2 400'],a:0,why:'Simple interest I = PRT/100 = (8 000 × 5 × 3)/100 = $1 200.',tech:'Read whether the question wants the interest or the total amount repaid. It is the commonest lost mark in this topic.'},
{id:'ma6',subj:'mathematics',strand:'ma-sets',form:2,diff:2,q:'In a class of 40 students, 25 study Spanish and 18 study French. 7 study both. How many study neither?',opts:['4','3','11','15'],a:0,why:'Students doing at least one = 25 + 18 − 7 = 36. Neither = 40 − 36 = 4.',tech:'Draw the Venn diagram and fill the intersection FIRST, then work outwards. Subtract the overlap so it is not counted twice.'},
{id:'ma7',subj:'mathematics',strand:'ma-measure',form:2,diff:2,q:'Find the area of a circle of radius 7 cm. Use π = 22/7.',opts:['154 cm²','44 cm²','49 cm²','308 cm²'],a:0,why:'A = πr² = 22/7 × 7 × 7 = 154 cm².',tech:'Area uses r², circumference uses 2r. Mixing them up is the single commonest circle error.'},
{id:'ma8',subj:'mathematics',strand:'ma-measure',form:3,diff:2,q:'A cylinder has radius 3 cm and height 10 cm. Taking π = 3.14, find its volume.',opts:['282.6 cm³','94.2 cm³','188.4 cm³','90 cm³'],a:0,why:'V = πr²h = 3.14 × 9 × 10 = 282.6 cm³.',tech:'Volume of any prism or cylinder = area of the cross-section × length. Learn one rule, not five.'},
{id:'ma9',subj:'mathematics',strand:'ma-stats',form:2,diff:1,q:'Find the mean of: 4, 7, 9, 12, 3',opts:['7','9','8','6'],a:0,why:'Sum = 35, and there are 5 values, so the mean = 35 ÷ 5 = 7.',tech:'Mean = add and divide. Median = order first, then take the middle. Mode = most frequent. Write the three definitions on your paper before you start the question.'},
{id:'ma10',subj:'mathematics',strand:'ma-stats',form:3,diff:2,q:'A bag contains 3 red and 5 blue marbles. One marble is drawn at random. What is the probability that it is red?',opts:['3/8','3/5','5/8','1/3'],a:0,why:'P(red) = number of red ÷ total = 3 ÷ 8 = 3/8.',tech:'The denominator is always the TOTAL. Count everything in the bag before you write the fraction.'},
{id:'ma11',subj:'mathematics',strand:'ma-algebra',form:1,diff:1,q:'Solve: 3x − 7 = 14',opts:['x = 7','x = 21','x = 2⅓','x = 3'],a:0,why:'Add 7 to both sides: 3x = 21. Divide by 3: x = 7.',tech:'Undo in reverse order — clear the addition or subtraction first, then the multiplication.'},
{id:'ma12',subj:'mathematics',strand:'ma-algebra',form:3,diff:2,q:'Factorise completely: x² + 5x + 6',opts:['(x + 2)(x + 3)','(x + 1)(x + 6)','(x − 2)(x − 3)','(x + 5)(x + 1)'],a:0,why:'Two numbers that multiply to 6 and add to 5 are 2 and 3, giving (x + 2)(x + 3).',tech:'Multiply your brackets back out to check. It takes ten seconds and catches every sign error.'},
{id:'ma13',subj:'mathematics',strand:'ma-algebra',form:3,diff:2,q:'Solve the pair: x + y = 10 and x − y = 4',opts:['x = 7, y = 3','x = 3, y = 7','x = 6, y = 4','x = 5, y = 5'],a:0,why:'Adding the equations eliminates y: 2x = 14, so x = 7. Substituting back gives y = 3.',tech:'When the same letter has opposite signs, ADD to eliminate. Same signs, subtract.'},
{id:'ma14',subj:'mathematics',strand:'ma-algebra',form:4,diff:3,q:'Solve: x² − 5x + 6 = 0',opts:['x = 2 or x = 3','x = −2 or x = −3','x = 1 or x = 6','x = 5 or x = 6'],a:0,why:'Factorising gives (x − 2)(x − 3) = 0, so x = 2 or x = 3.',tech:'A quadratic has two answers. Writing only one loses half the marks even when that one is right.'},
{id:'ma15',subj:'mathematics',strand:'ma-relations',form:3,diff:2,q:'Find the gradient of the line joining (1, 2) and (3, 8).',opts:['3','2','1/3','6'],a:0,why:'Gradient = (8 − 2) ÷ (3 − 1) = 6 ÷ 2 = 3.',tech:'Gradient is rise over run — the y difference on top. Taking them the other way up is the classic slip.'},
{id:'ma16',subj:'mathematics',strand:'ma-geom',form:2,diff:2,q:'What is the sum of the interior angles of a hexagon?',opts:['720°','1080°','540°','360°'],a:0,why:'Sum = (n − 2) × 180° = (6 − 2) × 180° = 720°.',tech:'Interior sum = (n − 2) × 180°. The EXTERIOR angles of any polygon always add to 360°.'},
{id:'ma17',subj:'mathematics',strand:'ma-geom',form:3,diff:2,q:'A right-angled triangle has legs of 6 cm and 8 cm. Find the hypotenuse.',opts:['10 cm','14 cm','48 cm','7 cm'],a:0,why:'By Pythagoras, h² = 6² + 8² = 36 + 64 = 100, so h = 10 cm.',tech:'The hypotenuse is always opposite the right angle and always the longest side. If your answer is smaller than a leg, it is wrong.'},
{id:'ma18',subj:'mathematics',strand:'ma-geom',form:4,diff:2,q:'What is the value of sin 30°?',opts:['0.5','1','0.866','0.577'],a:0,why:'sin 30° = 1/2 = 0.5. It comes from the half of an equilateral triangle.',tech:'Learn the exact values for 30°, 45° and 60°. They appear every year and save calculator time.'},
{id:'ma19',subj:'mathematics',strand:'ma-number',form:2,diff:1,q:'Divide $600 in the ratio 2 : 3. What is the LARGER share?',opts:['$360','$240','$300','$400'],a:0,why:'Total parts = 5, so one part = $120. The larger share is 3 parts = $360.',tech:'Always find the value of ONE part first. Then read carefully whether the question wants the larger or smaller share.'},
{id:'ma20',subj:'mathematics',strand:'ma-vectors',form:4,diff:3,q:'If a = (3, 1) and b = (−1, 4), find a + b.',opts:['(2, 5)','(4, −3)','(2, −3)','(−3, 4)'],a:0,why:'Add the matching components: (3 + (−1), 1 + 4) = (2, 5).',tech:'Add vectors component by component — never multiply them out. Keep the columns lined up on your page.'},

/* ============================ ENGLISH A ============================ */
{id:'ea1',subj:'english-a',strand:'ea-grammar',form:1,diff:1,q:'Choose the correct sentence.',opts:['Neither of the boys has finished his work.','Neither of the boys have finished their work.','Neither of the boys have finished his work.','Neither of the boys has finished their work.'],a:0,why:'"Neither" is singular, so it takes the singular verb "has" and the singular pronoun "his". The phrase "of the boys" does not change the subject.',tech:'Cover the phrase between the subject and the verb. The verb must agree with what is left.'},
{id:'ea2',subj:'english-a',strand:'ea-grammar',form:2,diff:2,q:'Which sentence uses the apostrophe correctly?',opts:['The students’ books were collected.','The students books’ were collected.','The student’s books were collected by all forty of them.','The students’s books were collected.'],a:0,why:'For a plural noun already ending in s, the apostrophe goes after the s: students’.',tech:'Ask who owns it. If the owner is plural and ends in s, apostrophe after. If singular, apostrophe then s.'},
{id:'ea3',subj:'english-a',strand:'ea-grammar',form:2,diff:2,q:'Identify the sentence with a dangling modifier.',opts:['Walking to school, the rain soaked Amara.','Walking to school, Amara was soaked by the rain.','As Amara walked to school, the rain soaked her.','Amara was soaked by the rain as she walked to school.'],a:0,why:'The opening phrase must describe the subject that follows. As written, the rain is walking to school.',tech:'After an -ing opening, the very next noun must be the one doing it. Check that noun every time.'},
{id:'ea4',subj:'english-a',strand:'ea-vocab',form:2,diff:2,q:'"The politician gave a *terse* reply." The word "terse" most nearly means:',opts:['brief and abrupt','long and detailed','warm and friendly','confused and unclear'],a:0,why:'Terse means using few words, often to the point of curtness.',tech:'When a word is unfamiliar, read the whole sentence for tone. The surrounding words usually narrow it to one option.'},
{id:'ea5',subj:'english-a',strand:'ea-comp',form:2,diff:2,q:'A question asks you to state what the writer IMPLIES about a character. This means you should:',opts:['work out what the writer suggests without stating directly','copy the sentence that describes the character','give your own opinion of the character','summarise the whole passage'],a:0,why:'To imply is to suggest indirectly. You infer it from the evidence rather than lifting a stated line.',tech:'"State" means lift it. "Suggest", "imply" or "infer" means work it out and then quote the evidence you used.'},
{id:'ea6',subj:'english-a',strand:'ea-summary',form:3,diff:3,q:'In a CSEC summary question, which is the MOST important rule?',opts:['Use your own words and keep within the word limit','Copy the best sentences from the passage','Include every example the writer gives','Write as much as you can to be safe'],a:0,why:'The summary tests whether you can identify main ideas and re-express them concisely in your own words within the stated limit.',tech:'Underline the main idea of each paragraph, then write one sentence per idea. Count your words — going over loses marks.'},
{id:'ea7',subj:'english-a',strand:'ea-arg',form:3,diff:2,q:'Which is the strongest thesis statement for an argumentative essay?',opts:['Secondary schools should ban mobile phones during class time because they measurably reduce concentration.','This essay is about mobile phones in school.','Mobile phones are a very interesting topic today.','There are many opinions about mobile phones in schools.'],a:0,why:'A thesis takes a clear, arguable position and signals the reason. The others announce a topic without arguing anything.',tech:'Your thesis must be something a reasonable person could disagree with. If nobody could argue back, it is not a thesis.'},
{id:'ea8',subj:'english-a',strand:'ea-narr',form:2,diff:2,q:'Which opening best shows rather than tells?',opts:['Her hands shook as she reached for the envelope.','She was very nervous about the envelope.','She felt nervous and worried and scared.','The envelope made her feel extremely nervous.'],a:0,why:'The physical detail of shaking hands lets the reader conclude she is nervous. The others simply name the emotion.',tech:'Show through action, gesture and detail. Naming the feeling is the fastest way to a mid-band mark.'},
{id:'ea9',subj:'english-a',strand:'ea-persuade',form:4,diff:2,q:'You must write a letter to the Principal requesting a change to the timetable. Which register is appropriate?',opts:['Formal and respectful, with a clear request and reasons','Casual and friendly, as if writing to a classmate','Emotional and demanding','Very short, with no explanation'],a:0,why:'Audience and purpose set register. A Principal is a formal audience, so the letter needs formal courtesy and reasoned support.',tech:'Before writing a directed piece, note the audience, purpose and format in the margin. Marks are awarded for all three.'},
{id:'ea10',subj:'english-a',strand:'ea-grammar',form:3,diff:2,q:'Which sentence is in the passive voice?',opts:['The report was written by the committee.','The committee wrote the report.','The committee is writing the report.','The committee will write the report.'],a:0,why:'In the passive, the subject receives the action. "The report" receives the writing, and the doer follows "by".',tech:'Passive = a form of "to be" + past participle. Useful in formal writing, but overusing it makes essays limp.'},

/* ============================ ENGLISH B ============================ */
{id:'eb1',subj:'english-b',strand:'eb-devices',form:1,diff:1,q:'"The wind whispered through the cane." This is an example of:',opts:['personification','simile','hyperbole','onomatopoeia'],a:0,why:'The wind is given a human ability — whispering — so it is personification.',tech:'Personification gives a human quality to something non-human. Simile needs "like" or "as".'},
{id:'eb2',subj:'english-b',strand:'eb-devices',form:1,diff:1,q:'"He was as stubborn as a mule." This is:',opts:['a simile','a metaphor','personification','an oxymoron'],a:0,why:'The comparison uses "as", which makes it a simile. A metaphor would say he WAS a mule.',tech:'Like or as → simile. Direct statement of one thing being another → metaphor.'},
{id:'eb3',subj:'english-b',strand:'eb-devices',form:2,diff:2,q:'"I have told you a million times." This is:',opts:['hyperbole','understatement','irony','alliteration'],a:0,why:'Hyperbole is deliberate exaggeration for effect — the speaker has not literally spoken a million times.',tech:'Do not just name the device. Say what EFFECT it creates — that is where the marks are.'},
{id:'eb4',subj:'english-b',strand:'eb-poetry',form:2,diff:2,q:'A poem with the rhyme scheme ABAB CDCD EFEF GG in fourteen lines is MOST likely:',opts:['a Shakespearean sonnet','a ballad','free verse','a haiku'],a:0,why:'Fourteen lines in three quatrains and a closing couplet with that scheme is the Shakespearean (English) sonnet form.',tech:'Count the lines first, then map the rhyme with letters down the margin. Form often points straight at the theme.'},
{id:'eb5',subj:'english-b',strand:'eb-poetry',form:2,diff:2,q:'The MOOD of a poem refers to:',opts:['the feeling the poem creates in the reader','the poet’s attitude to the subject','the number of syllables per line','the rhyme scheme'],a:0,why:'Mood is the atmosphere felt by the reader. The poet’s attitude is TONE — a different thing.',tech:'Tone belongs to the speaker, mood belongs to the reader. Examiners test that you can tell them apart.'},
{id:'eb6',subj:'english-b',strand:'eb-prose',form:3,diff:2,q:'In a novel, the term "protagonist" means:',opts:['the central character whose story we follow','the character who opposes the hero','the narrator of the story','the author’s spokesperson'],a:0,why:'The protagonist is the main character. The one who opposes them is the antagonist.',tech:'Do not assume the protagonist is likeable or the narrator. Many novels separate these deliberately.'},
{id:'eb7',subj:'english-b',strand:'eb-drama',form:3,diff:3,q:'Dramatic irony occurs when:',opts:['the audience knows something a character does not','a character says the opposite of what is meant','the ending is unexpected','two characters argue on stage'],a:0,why:'Dramatic irony depends on the gap between the audience’s knowledge and the character’s, which builds tension.',tech:'Verbal irony is in the words, situational irony is in the outcome, dramatic irony is in who knows what.'},
{id:'eb8',subj:'english-b',strand:'eb-essay',form:3,diff:3,q:'In a literature essay, the strongest paragraph structure is:',opts:['Point, Evidence, Explanation','Evidence, Point, Summary','Story retelling, then opinion','Quotation, then the next quotation'],a:0,why:'State the point, support it with a short quotation, then explain how that quotation proves the point and links to the question.',tech:'The Explanation is where most students lose marks. Never let a quotation stand without saying what it proves.'},
{id:'eb9',subj:'english-b',strand:'eb-short',form:2,diff:2,q:'Short stories usually differ from novels because they:',opts:['concentrate on a single effect or moment','always have a happy ending','contain no dialogue','are written only in the first person'],a:0,why:'The compressed form pushes a short story towards one central incident, effect or revelation.',tech:'In a short-story question, identify the turning point early — most questions circle back to it.'},
{id:'eb10',subj:'english-b',strand:'eb-devices',form:3,diff:2,q:'"The sea is a hungry dog" is:',opts:['a metaphor','a simile','alliteration','assonance'],a:0,why:'The sea is stated to BE a dog, with no "like" or "as", which makes it a metaphor.',tech:'When asked to comment on a metaphor, explain what quality is transferred — here, restless appetite and threat.'}
];

/* ===================== SCIENCES, HUMANITIES, LANGUAGES, TECHNICAL ===================== */
window.CSEC_QUESTIONS.push(

/* ---------------------------- PHYSICS ---------------------------- */
{id:'ph1',subj:'physics',strand:'ph-measure',form:1,diff:1,q:'The SI unit of force is the:',opts:['newton','joule','watt','pascal'],a:0,why:'Force is measured in newtons (N). The joule is energy, the watt is power and the pascal is pressure.',tech:'Learn the unit with the quantity from Form 1. Paper 01 gives away marks for units every single year.'},
{id:'ph2',subj:'physics',strand:'ph-mech',form:2,diff:1,q:'A runner covers 100 m in 20 s. What is the average speed?',opts:['5 m/s','2 000 m/s','0.2 m/s','20 m/s'],a:0,why:'Speed = distance ÷ time = 100 ÷ 20 = 5 m/s.',tech:'Write the formula, substitute, then compute. Examiners award a mark for the correct formula even if the arithmetic slips.'},
{id:'ph3',subj:'physics',strand:'ph-mech',form:2,diff:2,q:'A block has mass 200 g and volume 100 cm³. Find its density.',opts:['2 g/cm³','0.5 g/cm³','20 000 g/cm³','100 g/cm³'],a:0,why:'Density = mass ÷ volume = 200 ÷ 100 = 2 g/cm³.',tech:'Check the units match before dividing. Grams with cm³, kilograms with m³ — never mix them.'},
{id:'ph4',subj:'physics',strand:'ph-mech',form:3,diff:2,q:'Newton’s Third Law states that:',opts:['for every action there is an equal and opposite reaction','force equals mass times acceleration','an object stays at rest unless acted on by a force','energy cannot be created or destroyed'],a:0,why:'The Third Law describes paired forces acting on two different bodies, equal in size and opposite in direction.',tech:'The action-reaction pair acts on DIFFERENT objects. That is why they never cancel each other out.'},
{id:'ph5',subj:'physics',strand:'ph-waves',form:3,diff:2,q:'A wave has frequency 50 Hz and wavelength 2 m. Find its speed.',opts:['100 m/s','25 m/s','52 m/s','0.04 m/s'],a:0,why:'v = fλ = 50 × 2 = 100 m/s.',tech:'v = fλ is the one wave equation you must never forget. Rearrange it rather than learning three versions.'},
{id:'ph6',subj:'physics',strand:'ph-waves',form:2,diff:1,q:'When light reflects from a plane mirror, the angle of incidence is:',opts:['equal to the angle of reflection','twice the angle of reflection','always 90°','always zero'],a:0,why:'The law of reflection states that the angle of incidence equals the angle of reflection, both measured from the normal.',tech:'Both angles are measured from the NORMAL, not from the mirror surface. Draw the normal first.'},
{id:'ph7',subj:'physics',strand:'ph-elec',form:3,diff:2,q:'A 12 V supply drives current through a 4 Ω resistor. What is the current?',opts:['3 A','48 A','0.33 A','8 A'],a:0,why:'By Ohm’s law, I = V ÷ R = 12 ÷ 4 = 3 A.',tech:'V = IR. Cover the quantity you want with your finger to see whether to multiply or divide.'},
{id:'ph8',subj:'physics',strand:'ph-thermal',form:4,diff:2,q:'Latent heat is the energy needed to:',opts:['change the state of a substance without changing its temperature','raise the temperature of a substance','melt only solids','boil only liquids'],a:0,why:'During a change of state, the energy supplied breaks bonds between particles rather than raising temperature.',tech:'On a heating curve, the flat sections are where latent heat is being absorbed. Point to them in your answer.'},
{id:'ph9',subj:'physics',strand:'ph-atom',form:4,diff:3,q:'A radioactive sample has a half-life of 5 days. What fraction remains after 15 days?',opts:['1/8','1/3','1/15','1/5'],a:0,why:'15 days is three half-lives. After each one the amount halves: 1 → 1/2 → 1/4 → 1/8.',tech:'Count how many half-lives fit into the time given, then halve that many times. Never divide by the number of days.'},
{id:'ph10',subj:'physics',strand:'ph-mech',form:3,diff:2,q:'The moment of a force about a point is calculated as:',opts:['force × perpendicular distance from the point','force ÷ distance','force + distance','mass × acceleration'],a:0,why:'Moment = F × d, where d is the perpendicular distance from the pivot to the line of action of the force.',tech:'The distance must be PERPENDICULAR. If the force is at an angle, resolve it or use the perpendicular distance.'},

/* ---------------------------- CHEMISTRY ---------------------------- */
{id:'ch1',subj:'chemistry',strand:'ch-matter',form:1,diff:1,q:'Which method best separates sand from water?',opts:['filtration','distillation','chromatography','evaporation'],a:0,why:'Sand is insoluble, so it stays on the filter paper while water passes through as the filtrate.',tech:'Ask whether the solid dissolves. Insoluble → filter. Soluble and you want the solid → evaporate. Want the liquid → distil.'},
{id:'ch2',subj:'chemistry',strand:'ch-matter',form:2,diff:2,q:'Which technique would you use to separate the dyes in a sample of ink?',opts:['paper chromatography','filtration','decanting','magnetic separation'],a:0,why:'Chromatography separates dissolved substances by how far each travels up the paper with the solvent.',tech:'Always draw the pencil baseline ABOVE the solvent level. A pen line would dissolve and ruin the run.'},
{id:'ch3',subj:'chemistry',strand:'ch-atomic',form:2,diff:1,q:'The atomic number of an element tells you the number of:',opts:['protons in the nucleus','neutrons in the nucleus','protons and neutrons together','electron shells'],a:0,why:'Atomic number = proton number. In a neutral atom it also equals the number of electrons.',tech:'Mass number − atomic number = neutrons. Write that line at the top of the page in every structure question.'},
{id:'ch4',subj:'chemistry',strand:'ch-atomic',form:3,diff:2,q:'An ionic bond is formed when:',opts:['electrons are transferred from a metal to a non-metal','electrons are shared between two non-metals','protons move between atoms','atoms exchange neutrons'],a:0,why:'The metal loses electrons to form a positive ion and the non-metal gains them to form a negative ion; opposite charges attract.',tech:'Metal + non-metal → ionic. Non-metal + non-metal → covalent. That one line answers most bonding questions.'},
{id:'ch5',subj:'chemistry',strand:'ch-acids',form:2,diff:1,q:'A solution with pH 3 is:',opts:['acidic','alkaline','neutral','a strong base'],a:0,why:'The pH scale runs 0 to 14. Below 7 is acidic, 7 is neutral and above 7 is alkaline.',tech:'The LOWER the pH, the STRONGER the acid. Students routinely reverse this under pressure.'},
{id:'ch6',subj:'chemistry',strand:'ch-acids',form:3,diff:2,q:'Complete the general equation: acid + base →',opts:['salt + water','salt + hydrogen','salt + carbon dioxide + water','hydrogen + oxygen'],a:0,why:'Neutralisation of an acid by a base produces a salt and water only.',tech:'Acid + metal → salt + hydrogen. Acid + carbonate → salt + water + carbon dioxide. Learn all three pairs together.'},
{id:'ch7',subj:'chemistry',strand:'ch-mole',form:4,diff:2,q:'What is the relative molecular mass of water, H₂O? (H = 1, O = 16)',opts:['18','17','32','20'],a:0,why:'(2 × 1) + 16 = 18.',tech:'Multiply each atomic mass by the number of that atom BEFORE adding. The subscript applies only to the atom it follows.'},
{id:'ch8',subj:'chemistry',strand:'ch-organic',form:4,diff:2,q:'The general formula of the alkanes is:',opts:['CₙH₂ₙ₊₂','CₙH₂ₙ','CₙH₂ₙ₋₂','CₙHₙ'],a:0,why:'Alkanes are saturated hydrocarbons with only single bonds, giving CₙH₂ₙ₊₂. Alkenes are CₙH₂ₙ.',tech:'Alkane = all single bonds, saturated. Alkene = one double bond, unsaturated, decolourises bromine water.'},
{id:'ch9',subj:'chemistry',strand:'ch-inorg',form:3,diff:2,q:'A gas turns limewater milky. The gas is:',opts:['carbon dioxide','oxygen','hydrogen','ammonia'],a:0,why:'Carbon dioxide reacts with limewater (calcium hydroxide) to form insoluble calcium carbonate, which makes it cloudy.',tech:'Learn the four gas tests as a set: CO₂ milky limewater, O₂ relights a glowing splint, H₂ pops, NH₃ turns damp red litmus blue.'},
{id:'ch10',subj:'chemistry',strand:'ch-redox',form:4,diff:3,q:'During electrolysis, positive ions move towards the:',opts:['cathode','anode','electrolyte','battery'],a:0,why:'Positive ions (cations) are attracted to the negative electrode, which is the cathode, where they gain electrons.',tech:'Remember PANIC — Positive is Anode, Negative Is Cathode. Then cations go to the cathode.'},

/* ---------------------------- BIOLOGY ---------------------------- */
{id:'bi1',subj:'biology',strand:'bi-cells',form:1,diff:1,q:'Which structure is found in a plant cell but NOT in an animal cell?',opts:['cell wall','nucleus','cytoplasm','cell membrane'],a:0,why:'The cellulose cell wall, chloroplasts and a large permanent vacuole are plant features. All four options exist in both, except the cell wall.',tech:'Learn the three plant-only structures as a set: cell wall, chloroplast, large vacuole.'},
{id:'bi2',subj:'biology',strand:'bi-cells',form:2,diff:2,q:'Osmosis is the movement of:',opts:['water from high to low water potential through a partially permeable membrane','any substance from high to low concentration','water against a concentration gradient using energy','solutes through a membrane'],a:0,why:'Osmosis is specifically water moving down its water-potential gradient through a partially permeable membrane.',tech:'Say WATER and say PARTIALLY PERMEABLE MEMBRANE. A definition missing either word rarely scores full marks.'},
{id:'bi3',subj:'biology',strand:'bi-nutri',form:2,diff:2,q:'Which are the raw materials for photosynthesis?',opts:['carbon dioxide and water','oxygen and glucose','glucose and water','nitrogen and water'],a:0,why:'Carbon dioxide + water, in the presence of light and chlorophyll, produce glucose and oxygen.',tech:'Write the word equation before answering any photosynthesis question. It settles inputs versus outputs instantly.'},
{id:'bi4',subj:'biology',strand:'bi-nutri',form:3,diff:2,q:'Enzymes are:',opts:['proteins that speed up reactions and are affected by temperature and pH','carbohydrates that provide energy','lipids that store energy','minerals used in respiration'],a:0,why:'Enzymes are protein catalysts. High temperature or the wrong pH denatures the active site.',tech:'Use the word DENATURED, not "killed". Enzymes are molecules, not living things — that wording costs marks.'},
{id:'bi5',subj:'biology',strand:'bi-resp',form:3,diff:2,q:'The products of aerobic respiration in humans are:',opts:['carbon dioxide, water and energy','lactic acid and energy','glucose and oxygen','alcohol and carbon dioxide'],a:0,why:'Glucose + oxygen → carbon dioxide + water + energy. Lactic acid comes from ANAEROBIC respiration in muscle.',tech:'Anaerobic in muscle gives lactic acid; in yeast it gives alcohol and CO₂. Keep the two organisms separate.'},
{id:'bi6',subj:'biology',strand:'bi-nutri',form:2,diff:1,q:'Red blood cells transport oxygen because they contain:',opts:['haemoglobin','plasma','platelets','antibodies'],a:0,why:'Haemoglobin binds oxygen to form oxyhaemoglobin in the lungs and releases it in the tissues.',tech:'Match each blood component to its job: red cells oxygen, white cells defence, platelets clotting, plasma transport.'},
{id:'bi7',subj:'biology',strand:'bi-env',form:1,diff:1,q:'In a food chain, the first organism is always:',opts:['a producer','a herbivore','a carnivore','a decomposer'],a:0,why:'Food chains begin with a producer — usually a green plant that makes its own food by photosynthesis.',tech:'The arrows in a food chain show the direction ENERGY flows, not who eats whom. Draw them pointing away from the producer.'},
{id:'bi8',subj:'biology',strand:'bi-genes',form:4,diff:3,q:'A plant with genotype Tt is crossed with tt. What proportion of offspring will be tall if T is dominant?',opts:['50%','100%','75%','25%'],a:0,why:'The Punnett square gives Tt, Tt, tt, tt — half carry the dominant allele, so 50% are tall.',tech:'Always draw the Punnett square. An answer without it loses the method marks even when the ratio is right.'},
{id:'bi9',subj:'biology',strand:'bi-resp',form:3,diff:2,q:'Which is an example of EXCRETION rather than egestion?',opts:['removal of urea in urine','removal of faeces from the anus','removal of undigested fibre','removal of food that was never absorbed'],a:0,why:'Excretion removes waste made by the body’s own metabolism, such as urea. Egestion removes material that was never absorbed.',tech:'If the body MADE it, that is excretion. If it merely passed through, that is egestion.'},
{id:'bi10',subj:'biology',strand:'bi-health',form:3,diff:2,q:'Which disease is caused by a vector-borne virus common in the Caribbean?',opts:['dengue','diabetes','anaemia','asthma'],a:0,why:'Dengue is a viral disease transmitted by the Aedes aegypti mosquito, which is the vector. The others are not infectious.',tech:'Name the pathogen AND the vector when a question asks about transmission. Both carry marks.'},

/* ---------------------------- GEOGRAPHY ---------------------------- */
{id:'ge1',subj:'geography',strand:'ge-maps',form:1,diff:2,q:'When giving a grid reference, you read:',opts:['eastings first, then northings','northings first, then eastings','the largest number first','the contour value first'],a:0,why:'The convention is along the corridor then up the stairs — eastings (across) before northings (up).',tech:'"Along the corridor, up the stairs." Say it out loud in the exam; it prevents a reversed reference.'},
{id:'ge2',subj:'geography',strand:'ge-maps',form:2,diff:2,q:'On a map, contour lines drawn very close together indicate:',opts:['a steep slope','a gentle slope','flat land','a valley floor'],a:0,why:'Closely spaced contours mean a large height change over a short horizontal distance, which is a steep slope.',tech:'Close = steep, wide = gentle. Check the contour interval in the key before describing any relief.'},
{id:'ge3',subj:'geography',strand:'ge-tectonic',form:3,diff:2,q:'Volcanoes and earthquakes in the Eastern Caribbean occur mainly at a:',opts:['destructive (convergent) plate boundary','constructive plate boundary','conservative plate boundary','the centre of a plate'],a:0,why:'The Atlantic plate subducts beneath the Caribbean plate, producing the volcanic island arc of the Lesser Antilles.',tech:'Name the actual plates in your answer — Atlantic and Caribbean. Generic answers score in the lowest band.'},
{id:'ge4',subj:'geography',strand:'ge-weather',form:2,diff:1,q:'The Atlantic hurricane season officially runs from:',opts:['1 June to 30 November','1 January to 30 June','1 March to 31 August','1 September to 31 December'],a:0,why:'The official Atlantic hurricane season is 1 June to 30 November, when sea temperatures and conditions favour formation.',tech:'Learn the conditions needed too: sea above about 27 °C, low wind shear, and distance from the equator for the Coriolis effect.'},
{id:'ge5',subj:'geography',strand:'ge-weather',form:3,diff:2,q:'Relief rainfall occurs when:',opts:['moist air is forced to rise over high ground, cools and condenses','the ground heats and air rises by convection','two air masses of different temperature meet','cold air sinks over the sea'],a:0,why:'Air forced up a mountain barrier cools, condenses and rains on the windward side, leaving a rain shadow to leeward.',tech:'Three rainfall types: relief, convectional and frontal. Say which side is windward and name the rain shadow.'},
{id:'ge6',subj:'geography',strand:'ge-pop',form:2,diff:2,q:'Population density is calculated as:',opts:['total population ÷ land area','total population × land area','births minus deaths','population ÷ number of households'],a:0,why:'Density is people per square kilometre — population divided by area.',tech:'Density is how crowded; distribution is where people are. Questions often ask for one and students answer the other.'},
{id:'ge7',subj:'geography',strand:'ge-econ',form:3,diff:2,q:'Which is Trinidad and Tobago’s most important export sector by value?',opts:['petroleum and petrochemicals','tourism','agriculture','textiles'],a:0,why:'Oil, natural gas and downstream petrochemicals such as ammonia and methanol dominate the country’s export earnings.',tech:'For any Caribbean economy question, know one named example in detail rather than four in outline.'},
{id:'ge8',subj:'geography',strand:'ge-hazard',form:3,diff:2,q:'Which is a MITIGATION measure against earthquake damage?',opts:['enforcing building codes for earthquake-resistant construction','issuing a warning one hour before','evacuating after the shaking stops','rebuilding in the same way afterwards'],a:0,why:'Mitigation reduces impact before an event. Earthquakes cannot yet be predicted, so resistant construction is the main defence.',tech:'Separate preparation, mitigation and response in your notes. Questions almost always name one of the three.'},

/* ---------------------------- HISTORY ---------------------------- */
{id:'hi1',subj:'history',strand:'hi-indigenous',form:1,diff:1,q:'The indigenous people who mainly settled the Greater Antilles before European contact were the:',opts:['Taino','Maya','Aztec','Inca'],a:0,why:'The Taino occupied the Greater Antilles and the Bahamas. The Kalinago were concentrated in the Lesser Antilles.',tech:'Keep Taino and Kalinago straight by geography — Greater Antilles versus Lesser Antilles.'},
{id:'hi2',subj:'history',strand:'hi-indigenous',form:1,diff:1,q:'Columbus first reached the Caribbean in the year:',opts:['1492','1592','1445','1502'],a:0,why:'Columbus made landfall in the Bahamas in October 1492 on his first voyage.',tech:'Anchor the syllabus to a handful of dates: 1492, 1834, 1838, 1845, 1937, 1962. Everything else hangs off them.'},
{id:'hi3',subj:'history',strand:'hi-slavery',form:2,diff:2,q:'The Sugar Revolution in the Caribbean led MOST directly to:',opts:['a large increase in the demand for enslaved African labour','the end of plantation agriculture','the growth of small peasant farms','a decline in European settlement'],a:0,why:'Sugar required large estates and heavy year-round labour, which planters met by massively expanding the trade in enslaved Africans.',tech:'"Most directly" means pick the immediate consequence, not a later one. Read that phrase carefully.'},
{id:'hi4',subj:'history',strand:'hi-slavery',form:2,diff:2,q:'The Middle Passage refers to the:',opts:['voyage of enslaved Africans across the Atlantic to the Americas','journey of sugar from the Caribbean to Europe','march of captives to the African coast','return voyage of ships to Europe'],a:0,why:'It is the middle leg of the triangular trade, carrying enslaved Africans from West Africa to the Americas.',tech:'Be able to name all three legs of the triangular trade and the cargo on each.'},
{id:'hi5',subj:'history',strand:'hi-resist',form:3,diff:2,q:'The Haitian Revolution (1791–1804) is significant because it:',opts:['produced the first independent Black republic in the world','restored French control of Saint-Domingue','ended slavery throughout the Caribbean at once','was led by British abolitionists'],a:0,why:'The revolution defeated French, Spanish and British forces and established Haiti as the first Black republic in 1804.',tech:'Link Toussaint Louverture and Dessalines to their stages of the revolution. Named leaders lift an essay out of the middle band.'},
{id:'hi6',subj:'history',strand:'hi-emanc',form:3,diff:2,q:'Full freedom for the formerly enslaved in the British Caribbean came in:',opts:['1838, at the end of apprenticeship','1834, when the Act took effect','1833, when the Act was passed','1845'],a:0,why:'Emancipation took effect in 1834 but bound most people to apprenticeship. Full freedom came when apprenticeship ended in 1838.',tech:'1833 passed, 1834 in force, 1838 full freedom. Examiners test whether you know all three are different.'},
{id:'hi7',subj:'history',strand:'hi-adjust',form:3,diff:2,q:'The first ship carrying Indian indentured immigrants to Trinidad arrived in 1845. It was the:',opts:['Fatel Razack','Mayflower','Windrush','Santa Maria'],a:0,why:'The Fatel Razack arrived on 30 May 1845, an event now marked as Indian Arrival Day in Trinidad and Tobago.',tech:'For a Trinidad-based candidate this is a gift topic. Know the push and pull factors behind indentureship as well as the date.'},
{id:'hi8',subj:'history',strand:'hi-indep',form:4,diff:2,q:'The labour disturbances of 1937 in Trinidad were led in the oilfields by:',opts:['Uriah "Buzz" Butler','Eric Williams','Norman Manley','Alexander Bustamante'],a:0,why:'Butler led the oilfield workers’ protests of 1937, which fed directly into the growth of the trade union movement.',tech:'The 1930s labour unrest is the bridge from colonial rule to independence. Every "movements towards independence" essay should mention it.'},
{id:'hi9',subj:'history',strand:'hi-indep',form:4,diff:2,q:'The West Indies Federation existed between:',opts:['1958 and 1962','1945 and 1950','1962 and 1970','1973 and 1980'],a:0,why:'The Federation was formed in 1958 and dissolved in 1962 after Jamaica’s withdrawal following its referendum.',tech:'Do not confuse the Federation (1958–62) with CARICOM (1973). They are different bodies with different aims.'},
{id:'hi10',subj:'history',strand:'hi-skills',form:2,diff:2,q:'When a History question says "Explain TWO reasons", the best approach is to:',opts:['state each reason and develop it with specific evidence','list as many reasons as you can remember','describe the events in the order they happened','give your personal opinion'],a:0,why:'"Explain" requires reasons developed with supporting detail. Listing without development scores in the lowest band.',tech:'If it says TWO, give exactly two and develop both. A third undeveloped reason earns nothing and costs time.'},

/* ------------------------- SOCIAL STUDIES ------------------------- */
{id:'ss1',subj:'social-studies',strand:'ss-family',form:1,diff:1,q:'A family consisting of a mother, father and their children only is called a:',opts:['nuclear family','extended family','sibling household','single-parent family'],a:0,why:'The nuclear family is two parents and their children. Adding grandparents, aunts or uncles makes it extended.',tech:'Learn the family types with one Caribbean example each. Examples are what separate a Grade I from a Grade III.'},
{id:'ss2',subj:'social-studies',strand:'ss-family',form:2,diff:2,q:'Which is the PRIMARY agent of socialisation?',opts:['the family','the school','the media','peer groups'],a:0,why:'The family is primary because it is the first and most influential agent, shaping values before any other institution.',tech:'Primary means first and most formative. School, peers, media and religion are secondary agents.'},
{id:'ss3',subj:'social-studies',strand:'ss-region',form:3,diff:2,q:'CARICOM was established by the Treaty of Chaguaramas in:',opts:['1973','1958','1962','1989'],a:0,why:'The Treaty of Chaguaramas established the Caribbean Community and Common Market in 1973.',tech:'1973 CARICOM, 1989 Grand Anse Declaration leading to the CSME. Two dates, two different achievements.'},
{id:'ss4',subj:'social-studies',strand:'ss-region',form:3,diff:2,q:'The CSME is intended to allow the free movement of:',opts:['goods, services, capital and skilled labour','goods only','people on holiday only','currency only'],a:0,why:'The CARICOM Single Market and Economy provides for free movement of goods, services, capital and approved categories of skilled labour.',tech:'Note that labour movement is for APPROVED CATEGORIES, not everyone. That precision earns the mark.'},
{id:'ss5',subj:'social-studies',strand:'ss-gov',form:2,diff:2,q:'In Trinidad and Tobago, the arm of government that makes laws is the:',opts:['legislature','judiciary','executive','civil service'],a:0,why:'The legislature (Parliament) makes law, the executive implements it and the judiciary interprets it.',tech:'Three arms, three verbs: make, implement, interpret. That sentence answers half the government questions.'},
{id:'ss6',subj:'social-studies',strand:'ss-research',form:4,diff:2,q:'In an SBA, the statement of the problem should:',opts:['clearly identify what is being investigated and where','list all your findings','thank everyone who helped','describe your conclusion'],a:0,why:'The statement of the problem sets out the specific issue, the location and the scope of the investigation.',tech:'Keep the statement narrow enough to research with one questionnaire. Broad topics cannot be evidenced and lose marks.'},

/* ---------------------------- SPANISH ---------------------------- */
{id:'sp1',subj:'spanish',strand:'sp-gram',form:1,diff:1,q:'Complete: "Yo ___ estudiante."',opts:['soy','estoy','tengo','es'],a:0,why:'"Ser" is used for permanent characteristics and identity, so "yo soy estudiante".',tech:'SER for identity, origin and permanent traits. ESTAR for location and temporary states. It is tested every year.'},
{id:'sp2',subj:'spanish',strand:'sp-gram',form:2,diff:2,q:'Complete: "La biblioteca ___ cerca de la escuela."',opts:['está','es','son','tiene'],a:0,why:'Location always takes "estar", so "la biblioteca está cerca".',tech:'If the sentence says WHERE something is, use estar — with no exceptions at CSEC level.'},
{id:'sp3',subj:'spanish',strand:'sp-gram',form:3,diff:2,q:'What is the "yo" form of "hablar" in the preterite tense?',opts:['hablé','hablo','hablaba','hablaré'],a:0,why:'The preterite yo form of an -ar verb ends in -é: hablé (I spoke).',tech:'Preterite = completed action. Imperfect = used to / was doing. The accent on -é is part of the mark.'},
{id:'sp4',subj:'spanish',strand:'sp-themes',form:1,diff:1,q:'"¿Cómo te llamas?" means:',opts:['What is your name?','How are you?','Where do you live?','How old are you?'],a:0,why:'Literally "how do you call yourself" — it asks for the person’s name.',tech:'Learn the core question words as a block: qué, quién, dónde, cuándo, cómo, por qué, cuánto.'},
{id:'sp5',subj:'spanish',strand:'sp-themes',form:1,diff:1,q:'Which is the correct definite article: "___ casa"?',opts:['la','el','los','las'],a:0,why:'"Casa" is a feminine singular noun, so it takes "la".',tech:'Most nouns ending in -a are feminine and -o masculine. Learn the exceptions (el día, la mano) as a short list.'},
{id:'sp6',subj:'spanish',strand:'sp-read',form:2,diff:2,q:'A sign reads "PROHIBIDO FUMAR". It means:',opts:['No smoking','No entry','No parking','No photographs'],a:0,why:'"Prohibido" means forbidden and "fumar" means to smoke.',tech:'In the reading paper, signs and notices come first and are the quickest marks. Do not rush them.'},

/* ---------------------------- FRENCH ---------------------------- */
{id:'fr1',subj:'french',strand:'fr-gram',form:1,diff:1,q:'Complete: "Je ___ quatorze ans."',opts:['ai','suis','est','as'],a:0,why:'French expresses age with "avoir" — j’ai quatorze ans, literally "I have fourteen years".',tech:'Age, hunger, thirst and fear all use AVOIR in French, not être. English speakers reach for "suis" and lose the mark.'},
{id:'fr2',subj:'french',strand:'fr-gram',form:3,diff:2,q:'Which auxiliary does "aller" take in the passé composé?',opts:['être','avoir','faire','venir'],a:0,why:'"Aller" is one of the verbs of motion that take "être": je suis allé(e).',tech:'Learn the être verbs with DR & MRS VANDERTRAMP, and remember the past participle must agree with the subject.'},
{id:'fr3',subj:'french',strand:'fr-themes',form:1,diff:1,q:'"Comment t’appelles-tu ?" means:',opts:['What is your name?','How old are you?','Where are you from?','How are you?'],a:0,why:'Literally "how do you call yourself" — it asks for the name.',tech:'Do not confuse it with "Comment ça va ?" which asks how you are.'},
{id:'fr4',subj:'french',strand:'fr-gram',form:1,diff:1,q:'Which is the correct definite article: "___ école"?',opts:['l’','le','la','les'],a:0,why:'"École" begins with a vowel, so le/la elides to l’.',tech:'Before a vowel or silent h, le and la both become l’. The gender still matters for adjective agreement.'},
{id:'fr5',subj:'french',strand:'fr-read',form:2,diff:2,q:'A notice reads "DÉFENSE DE STATIONNER". It means:',opts:['No parking','No smoking','No entry','Do not touch'],a:0,why:'"Stationner" means to park, and "défense de" means it is forbidden.',tech:'"Défense de" and "interdit" both mean forbidden. Learn the common public notices — they are free marks.'},
{id:'fr6',subj:'french',strand:'fr-write',form:3,diff:2,q:'In a CSEC directed writing task with a 130–150 word limit, writing 200 words will:',opts:['lose marks, because the limit is part of the task','gain marks for extra detail','make no difference','only matter in the oral'],a:0,why:'The word limit is a stated requirement; exceeding it is penalised regardless of quality.',tech:'Count in blocks of ten as you write. Finishing inside the limit is worth more than one extra idea.'},

/* -------------------------- VISUAL ARTS -------------------------- */
{id:'va1',subj:'visual-arts',strand:'va-elements',form:1,diff:1,q:'The three primary colours are:',opts:['red, yellow and blue','red, green and blue','orange, green and purple','black, white and grey'],a:0,why:'In pigment, red, yellow and blue cannot be mixed from other colours and combine to make the secondaries.',tech:'Primary → secondary → tertiary. Be ready to name which two primaries make each secondary.'},
{id:'va2',subj:'visual-arts',strand:'va-elements',form:2,diff:2,q:'Which pair are complementary colours?',opts:['red and green','red and orange','blue and purple','yellow and orange'],a:0,why:'Complementary colours sit opposite each other on the colour wheel. Red faces green, blue faces orange, yellow faces purple.',tech:'Complementary pairs placed together intensify each other. Say that effect when you use the term in a critique.'},
{id:'va3',subj:'visual-arts',strand:'va-elements',form:2,diff:2,q:'Balance, rhythm, contrast and unity are:',opts:['principles of design','elements of art','types of media','art movements'],a:0,why:'Elements are the building blocks — line, shape, colour, texture, form, space, value. Principles are how they are arranged.',tech:'Elements are WHAT you use, principles are HOW you arrange them. Critique questions want both.'},
{id:'va4',subj:'visual-arts',strand:'va-draw',form:3,diff:2,q:'In one-point perspective, all receding parallel lines converge at:',opts:['a single vanishing point on the horizon','two vanishing points','the centre of the paper','the top corner'],a:0,why:'One-point perspective has a single vanishing point on the eye-level horizon line.',tech:'Draw the horizon line and mark the vanishing point before anything else. Freehand guessing is visible to the examiner.'},

/* ------------------- PHYSICAL EDUCATION & SPORT ------------------- */
{id:'pe1',subj:'physical-education',strand:'pe-fitness',form:1,diff:1,q:'Which is a component of HEALTH-related fitness?',opts:['cardiovascular endurance','agility','reaction time','coordination'],a:0,why:'Health-related components are cardiovascular endurance, muscular strength, muscular endurance, flexibility and body composition. Agility, reaction time and coordination are skill-related.',tech:'Learn the five health-related and six skill-related components as two separate lists. Questions test the split.'},
{id:'pe2',subj:'physical-education',strand:'pe-injury',form:2,diff:1,q:'RICE, the immediate treatment for a soft-tissue injury, stands for:',opts:['Rest, Ice, Compression, Elevation','Run, Ice, Cool, Exercise','Rest, Injure, Cool, Extend','Rest, Immobilise, Cover, Elevate'],a:0,why:'Rest, Ice, Compression and Elevation limit swelling and pain in the first 48 hours after a sprain or strain.',tech:'Be able to say WHY each step works — reduces blood flow, limits swelling. Naming alone is a one-mark answer.'},
{id:'pe3',subj:'physical-education',strand:'pe-fitness',form:2,diff:2,q:'The FITT principle stands for:',opts:['Frequency, Intensity, Time, Type','Fitness, Interval, Training, Technique','Force, Impact, Tempo, Timing','Flexibility, Intensity, Training, Type'],a:0,why:'FITT is the framework for designing a training programme: how often, how hard, how long and what kind.',tech:'Apply FITT to a named sport in your answer. Generic programmes score low.'},
{id:'pe4',subj:'physical-education',strand:'pe-anatomy',form:3,diff:2,q:'Which is NOT a function of the skeleton?',opts:['production of hormones for growth','support of the body','protection of vital organs','production of blood cells'],a:0,why:'The skeleton supports, protects, allows movement, stores minerals and makes blood cells in the marrow. Hormones are made by the endocrine glands.',tech:'"NOT" questions catch tired candidates. Underline the word NOT before you look at the options.'},
{id:'pe5',subj:'physical-education',strand:'pe-nutri',form:2,diff:2,q:'Which nutrient is the body’s MAIN source of energy for high-intensity exercise?',opts:['carbohydrate','protein','fat','vitamins'],a:0,why:'Carbohydrate is broken down to glucose, the fastest fuel available and the one used at high intensity.',tech:'Fat fuels low-intensity endurance work; protein is for growth and repair, not a main fuel.'},

/* --------------------- INFORMATION TECHNOLOGY --------------------- */
{id:'it1',subj:'information-technology',strand:'it-hardware',form:1,diff:1,q:'Which of the following is an INPUT device?',opts:['scanner','monitor','printer','speaker'],a:0,why:'A scanner sends data into the computer. Monitors, printers and speakers all output data.',tech:'Ask which way the data flows — into the machine is input, out of it is output.'},
{id:'it2',subj:'information-technology',strand:'it-hardware',form:2,diff:2,q:'RAM is described as volatile because it:',opts:['loses its contents when power is removed','can be written to only once','stores data permanently','is slower than the hard disk'],a:0,why:'Volatile memory needs continuous power. Switch the machine off and RAM is cleared; ROM and disk storage are not.',tech:'RAM volatile and temporary, ROM non-volatile and permanent. One sentence, several marks a year.'},
{id:'it3',subj:'information-technology',strand:'it-data',form:2,diff:2,q:'The binary number 1011 is equal to which decimal number?',opts:['11','13','9','15'],a:0,why:'Place values 8, 4, 2, 1 give (1×8) + (0×4) + (1×2) + (1×1) = 11.',tech:'Write the place values 8 4 2 1 above the digits before converting. It removes the guesswork.'},
{id:'it4',subj:'information-technology',strand:'it-solve',form:3,diff:2,q:'In a flowchart, the diamond shape represents:',opts:['a decision','a process','input or output','the start or end'],a:0,why:'The diamond is a decision with two exit paths, normally labelled Yes and No.',tech:'Oval start/stop, parallelogram input/output, rectangle process, diamond decision. Label BOTH branches of every diamond.'},
{id:'it5',subj:'information-technology',strand:'it-productivity',form:2,diff:2,q:'In a spreadsheet, which formula adds the values in cells A1 to A10?',opts:['=SUM(A1:A10)','=ADD(A1:A10)','=TOTAL(A1-A10)','=SUM(A1+A10)'],a:0,why:'SUM with a colon range adds every cell from A1 through A10 inclusive.',tech:'Every formula starts with =. The colon means a RANGE; a comma means a list of separate cells.'},
{id:'it6',subj:'information-technology',strand:'it-impact',form:3,diff:2,q:'Checking that a date of birth entered as 32/13/2011 is impossible is an example of:',opts:['validation','verification','encryption','compression'],a:0,why:'Validation checks that data is reasonable and within allowed limits. Verification checks it was copied accurately.',tech:'Validation = sensible. Verification = accurate. Give an example of each and the marks follow.'},
{id:'it7',subj:'information-technology',strand:'it-solve',form:4,diff:3,q:'In an IPO chart, the "P" stands for:',opts:['Processing','Program','Print','Procedure'],a:0,why:'IPO stands for Input, Processing and Output — the three stages of defining a problem before designing an algorithm.',tech:'Fill the Output column first. Knowing what you must produce tells you what inputs and processing you need.'}
);
